    /** flat boxes for the menu preview: cape number 5 is the first of these capes */
    public static List<Cosmetics.Box> boxes(int cape) {
        List<Cosmetics.Box> out = new ArrayList<>();
        int k = cape - 5;
        if (k < 0 || k >= ART.length) return out;
        String[] rows = ART[k];
        for (int r = 0; r < 16; r++) {
            int c = 0;
            while (c < 10) {
                int c2 = c;
                while (c2 + 1 < 10 && rows[r].charAt(c2 + 1) == rows[r].charAt(c)) c2++;
                int ci = Character.digit(rows[r].charAt(c), 16);
                out.add(new Cosmetics.Box(6 + 2 * c, 16 + 3 * r, 2 * (c2 - c + 1), 3, 1.2f, 4.6f, PAL[k][ci]));
                c = c2 + 1;
            }
        }
        return out;
    }
